// Serves Get-Nibble.exe: the native Nibble installer (WinForms, no console window).
// Downloads the SHA-256-verified Electron runtime, lays down the app, makes shortcuts,
// registers in Add/Remove Programs, and doubles as its own uninstaller (/uninstall).
// Stored gzip+base64 so it can live in source; checked against its SHA-256 before it's ever served.
// This file is the build from .github/workflows/win-setup.yml (compiled on Windows against .NET
// Framework 4 and self-tested there). Don't embed a Linux/mono build: it can bind to APIs Windows lacks.
import { gunzipSync } from 'zlib';
import { createHash } from 'crypto';

const SHA256 = '624a5752381bfe95d4fb34bdd720cb1274fbfdb5e920b4e7b05f2699b2200367';
const GZ =
  '';

export function GET(req) {
  try {
    const buf = gunzipSync(Buffer.from(GZ, 'base64'));
    if (createHash('sha256').update(buf).digest('hex') !== SHA256) throw new Error('checksum');
    return new Response(buf, {
      headers: {
        'Content-Type': 'application/vnd.microsoft.portable-executable',
        'Content-Disposition': 'attachment; filename="Get-Nibble.exe"',
        'Content-Length': String(buf.length),
        'Cache-Control': 'no-cache, max-age=0',
        'X-Nibble-Sha256': SHA256,
      },
    });
  } catch (_) {
    // never hand out a broken file: fall back to the script installer
    return Response.redirect(new URL('/install.cmd', req.url), 302);
  }
}
